<?php
namespace App\Controllers\Admin;use App\Support\App;
final class SettingController{public function save():never{App::requireAdmin();$in=App::input();$allowed=['site_name','site_logo','registration_enabled','deposit_manual_enabled','deposit_auto_enabled','ceirgo_base_url','ceirgo_api_key','gobiz_qr_string','gobiz_token','gobiz_journal_url','jago_gmail_client_id','jago_gmail_client_secret','jago_gmail_refresh_token','bot_enabled','bot_number','bot_api_url','bot_api_token'];foreach($allowed as $k)if(array_key_exists($k,$in))App::set($k,(string)$in[$k]);foreach(['manual','gobiz','jago'] as $g){$v=(int)!empty($in['gateway_'.$g]);App::db()->prepare('UPDATE payment_gateways SET is_active=? WHERE code=?')->execute([$v,$g]);}App::json(['ok'=>true,'message'=>'Settings updated']);}}